class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        if not nums:
            return 0

        M = max(nums)
        # best[y][d] stores the maximum length of a valid subsequence 
        # ending with value y whose last difference is at least d.
        # We need size M + 1 for rows (values 1 to M)
        # We need size M + 2 for columns (differences 0 to M, plus an extra M+1 for base case)
        best = [[0] * (M + 2) for _ in range(M + 1)]
        ans = 1

        for x in nums:
            row = best[x]

